import java.io.*;import java.lang.management.*;import java.net.*;import java.nio.charset.*;import java.util.*;import java.util.regex.*;
import com.sun.tools.javac.util.Context;import com.sun.tools.javac.util.Names;
/** Identical caller bytecode; only the separately compiled f360 library overlays differ. */
public class PublicCallerProbe {
 static final com.sun.management.ThreadMXBean MX=(com.sun.management.ThreadMXBean)ManagementFactory.getThreadMXBean();static volatile long sink;static volatile Object objectSink;
 interface Job{long run()throws Exception;}record C(String name,Job job){}
 static ArrayList<C> cases()throws Exception{ArrayList<C>cs=new ArrayList<>();
 for(int n:new int[]{16,4096})for(String kind:new String[]{"none","sparse","dense","early"}){float[]a=new float[n],b=new float[n];Arrays.fill(a,1);Arrays.fill(b,1);if(kind.equals("sparse")){a[1]=Float.intBitsToFloat(0x7fc00001);b[1]=Float.intBitsToFloat(0xffc00002);}if(kind.equals("dense")){Arrays.fill(a,Float.intBitsToFloat(0x7fc00001));Arrays.fill(b,Float.intBitsToFloat(0xffc00002));}if(kind.equals("early"))b[0]=2;cs.add(new C("arrays_"+kind+"_"+n,()->Arrays.mismatch(a,b)));}
 for(int n:new int[]{8,32,256}){Names names=new Names(new Context());byte[][]words=new byte[64][];com.sun.tools.javac.util.Name[]canonical=new com.sun.tools.javac.util.Name[64];for(int k=0;k<64;k++){words[k]=("name"+k+"a".repeat(n)).substring(0,n).getBytes(StandardCharsets.UTF_8);canonical[k]=names.fromUtf(words[k]);}int[]index={0};cs.add(new C("javac_names_hit_"+n,()->{int k=(index[0]++)&63;byte[]b=words[k];return names.fromUtf(b)==canonical[k]?1:0;}));}
 for(int n:new int[]{16,256,4096})for(String kind:new String[]{"ascii","sparse","dense"}){String s=kind.equals("ascii")?"a".repeat(n):kind.equals("sparse")?"é"+"a".repeat(n-1):"é".repeat(n);ByteArrayOutputStream out=new ByteArrayOutputStream(n*4+2);DataOutputStream dos=new DataOutputStream(out);dos.writeUTF(s);byte[]wire=out.toByteArray();ByteArrayInputStream in=new ByteArrayInputStream(wire);DataInputStream dis=new DataInputStream(in);cs.add(new C("writeUTF_"+kind+"_"+n,()->{out.reset();dos.writeUTF(s);return out.size();}));cs.add(new C("readUTF_"+kind+"_"+n,()->{in.reset();String x=dis.readUTF();objectSink=x;return x.length();}));}
 for(String name:new String[]{"plain_short","plain_long","mixed_sparse","mixed_dense","malformed"}){String s=switch(name){case "plain_short"->"abcd";case "plain_long"->"a".repeat(4096);case "mixed_sparse"->"a".repeat(2048)+"%41+"+"b".repeat(2048);case "mixed_dense"->"a+b%41".repeat(128);default->"a".repeat(256)+"%GG";};cs.add(new C("url_"+name,()->{try{String x=URLDecoder.decode(s,StandardCharsets.UTF_8);objectSink=x;return x.length();}catch(IllegalArgumentException e){objectSink=e;return -1;}}));}
 for(String name:new String[]{"small","long_absent","late_hit","continuation_fail","custom"}){String needle=name.equals("small")?"abc":"abcdefghijklmnop";String text=switch(name){case "small"->"abc";case "late_hit"->"x".repeat(4096)+needle;case "continuation_fail"->(needle+"X").repeat(128);default->"x".repeat(4096);};String pattern=name.equals("continuation_fail")?needle+"(?=Z)":needle;CharSequence input=name.equals("custom")?new StringBuilder(text):text;Matcher m=Pattern.compile(pattern).matcher(input);cs.add(new C("regex_reuse_"+name,()->{m.reset(input);boolean b=m.find();return b?m.start():m.hitEnd()?-1:-2;}));}
 for(int n:new int[]{3,32}){String pat="a".repeat(n)+"z",text="x".repeat(256)+pat;cs.add(new C("regex_compile_match_"+n,()->{Matcher m=Pattern.compile(pat).matcher(text);boolean b=m.find();objectSink=m;return b?m.start():-1;}));}
 return cs;}
 static void run(Job j,int n)throws Exception{long x=0;for(int i=0;i<n;i++)x+=j.run();sink=x;}
 public static void main(String[]args)throws Exception{for(C c:cases()){for(int w=0;w<3;w++)run(c.job,2000);int reps=5000;long t=System.nanoTime();run(c.job,reps);long dt=System.nanoTime()-t;reps=(int)Math.min(150000,Math.max(500,30_000_000.0*reps/Math.max(1,dt)));run(c.job,reps);long alloc=MX.getThreadAllocatedBytes(Thread.currentThread().threadId());t=System.nanoTime();run(c.job,reps);dt=System.nanoTime()-t;alloc=MX.getThreadAllocatedBytes(Thread.currentThread().threadId())-alloc;System.out.printf(Locale.ROOT,"%s,%s,%.5f,%.5f,%d%n",args[0],c.name,(double)dt/reps,(double)alloc/reps,reps);}}
}
